// Momentum page: mode tabs and the example-practice recap. Every number shown in example
// mode comes from data/momentum_examples.json, generated by analysis/export_momentum.py.
import { METRICS, METRIC_INFO, narrate } from "./narrative.js";
import { COLOURS, el, radioGroup, renderContinuation, renderDayChart, renderMetrics, renderMilestones, renderNarrative, renderNext, renderStories } from "./recap-view.js";
import { initPreview } from "./preview.js";
import { initReflect } from "./reflect-view.js";
import { store } from "./store.js";
import { initValue } from "./value-view.js";
import { CLIENT_SOURCES, CLIENT_SOURCE_INFO } from "./workflows.js";

const DATA_URL = "data/momentum_examples.json";
const CHECKPOINTS = [3, 7, 14];
const TRIAL_DAYS = 14;
const MIN_BAR_SCALE = 3;
const $ = (sel) => document.querySelector(sel);
const announcer = $("[data-announce]");
const state = { data: null, practice: 0, day: 14 };

// Links can open a specific example and checkpoint, e.g. ?example=A&day=7#momentum (used by the email).
function linkedState() {
  const params = new URLSearchParams(location.search);
  const letter = (params.get("example") ?? "").toUpperCase();
  const index = letter.length === 1 ? "ABC".indexOf(letter) : -1;
  const day = Number(params.get("day"));
  if (index >= 0) state.practice = index;
  if ([3, 7, 14].includes(day)) state.day = day;
}

function practiceDescription(p) {
  const team = p.team_size === "1" ? "solo practice" : `team of ${p.team_size}`;
  return `${p.profession}, ${team}`;
}

function scaleFor(practices) {
  return Object.fromEntries(METRICS.map((m) => [m, Math.max(MIN_BAR_SCALE, ...practices.map((p) => p.snapshots["14"].counts[m]))]));
}

function renderChart(p, day) {
  const columns = Array.from({ length: TRIAL_DAYS }, (_, d) => Object.fromEntries(METRICS.map((m) => [m, p.daily[m][d]])));
  renderDayChart($("[data-ex-chart]"), columns, day);
  $("[data-ex-chart-sub]").textContent = day < TRIAL_DAYS ? `Days 1–${day} shown; later days are dimmed` : "All 14 trial days";
}

/** Days (up to the checkpoint) on which each tracked workflow was recorded. */
function activeDaysByMetric(p, day) {
  return Object.fromEntries(METRICS.map((m) => [m, p.daily[m].slice(0, day).filter((n) => n > 0).length]));
}

function sourceDetail(sources) {
  return CLIENT_SOURCES.filter((s) => sources[s] > 0).map((s) => `${sources[s]} ${CLIENT_SOURCE_INFO[s].label.toLowerCase()}`).join(" · ");
}

// Client records get one milestone per source, so imported records read as existing clients.
function milestoneItems(p, day) {
  const items = [
    ...Object.entries(p.milestones).filter(([m]) => m !== "client_created").map(([metric, ms]) => ({ metric, ms })),
    ...Object.entries(p.client_milestones).map(([source, ms]) => ({ metric: "client_created", ms, label: CLIENT_SOURCE_INFO[source].milestone })),
  ];
  return items
    .sort((a, b) => a.ms.trial_day - b.ms.trial_day)
    .map(({ metric, ms, label }) => ({
      metric,
      label,
      done: ms.trial_day <= day,
      detail: ms.trial_day <= day ? `Day ${ms.trial_day} · ${ms.local_date}` : "",
    }));
}

/** One example practice at one checkpoint: its snapshot, the previous checkpoint and the narrative context. */
function exampleAt(index, day) {
  const p = state.data.practices[index];
  const idx = CHECKPOINTS.indexOf(day);
  const prevDay = idx > 0 ? CHECKPOINTS[idx - 1] : null;
  const snap = p.snapshots[String(day)];
  const prevSnap = prevDay ? p.snapshots[String(prevDay)] : null;
  const ctx = {
    counts: snap.counts, day, prev: prevSnap?.counts ?? null, prevDay,
    clientSources: snap.client_sources, activeDaysByMetric: activeDaysByMetric(p, day),
    workflows: snap.workflow_list, prevWorkflows: prevSnap?.workflow_list ?? null,
  };
  return { p, snap, prevSnap, prevDay, ctx };
}

function renderExample() {
  const day = state.day;
  const idx = CHECKPOINTS.indexOf(day);
  const { p, snap, prevSnap, prevDay, ctx } = exampleAt(state.practice, day);
  const story = narrate({ ...ctx, priority: store.state.priority });
  // Every practice at every checkpoint, so the reflection can switch between them.
  state.data.practices.forEach((_, i) => CHECKPOINTS.forEach((d) => {
    const other = exampleAt(i, d);
    store.putRecap(`example-${i}@${d}`, { title: other.p.label, day: d, own: false, ctx: other.ctx, hasEarlier: Boolean(other.prevDay), counts: other.snap.counts });
  }));
  store.refreshRecap();

  $("[data-ex-kicker]").textContent = `${p.label} · ${practiceDescription(p)} · Day ${day} recap`;
  $("[data-ex-headline]").textContent = story.headline;
  renderNarrative($("[data-ex-sentences]"), story);
  renderContinuation($("[data-ex-continuation]"), story.continuation);
  renderStories($("[data-ex-stories]"), story.stories);
  renderChart(p, day);
  renderMetrics($("[data-ex-metrics]"), {
    counts: snap.counts, prev: prevSnap?.counts ?? null, prevDay, scale: scaleFor(state.data.practices),
    details: { client_created: sourceDetail(snap.client_sources) },
  });
  renderMilestones($("[data-ex-milestones]"), milestoneItems(p, day));
  renderNext($("[data-ex-next]"), story.nextStep);
  $("[data-cp-fill]").style.width = `${(idx / (CHECKPOINTS.length - 1)) * 100}%`;
  document.querySelectorAll("[data-checkpoints] .cp").forEach((b, i) => b.classList.toggle("is-reached", i <= idx));
  announcer.textContent = `${p.label}, Day ${day}: ${story.headline}`;
}

function initExamples() {
  const practiceWrap = $("[data-practices]");
  const practiceButtons = state.data.practices.map((p) =>
    el("button", { class: "practice", type: "button", role: "radio", "aria-checked": "false" },
      el("span", { class: "pattern" }, p.pattern),
      el("b", {}, p.label),
      el("small", {}, practiceDescription(p))));
  practiceWrap.append(...practiceButtons);
  radioGroup(practiceWrap, practiceButtons, (i) => {
    state.practice = i;
    store.setSource(`example-${i}`);
    renderExample();
  })(state.practice, false);

  const cpWrap = $("[data-checkpoints]");
  const cpButtons = CHECKPOINTS.map((d) => el("button", { class: "cp", type: "button", role: "radio", "aria-checked": "false" }, `Day ${d}`));
  cpWrap.append(...cpButtons);
  radioGroup(cpWrap, cpButtons, (i) => {
    state.day = CHECKPOINTS[i];
    renderExample();
  })(CHECKPOINTS.indexOf(state.day), false);

  $("[data-legend]").replaceChildren(...METRICS.map((m) =>
    el("li", { style: { "--c": COLOURS[m] } }, el("i", { "aria-hidden": "true" }), METRIC_INFO[m].label)));
}

function initModes() {
  const tabs = [...document.querySelectorAll(".mode")];
  const thumb = $(".mode-thumb");
  const place = () => {
    const on = tabs.find((t) => t.getAttribute("aria-selected") === "true");
    thumb.style.width = `${on.offsetWidth}px`;
    thumb.style.transform = `translateX(${on.offsetLeft}px)`;
  };
  const setMode = (mode, focus = false) => {
    tabs.forEach((t) => {
      const on = t.dataset.mode === mode;
      t.setAttribute("aria-selected", String(on));
      t.tabIndex = on ? 0 : -1;
      if (on && focus) t.focus();
    });
    $("#panel-examples").hidden = mode !== "examples";
    $("#panel-preview").hidden = mode !== "preview";
    place();
    store.setMode(mode);
  };
  tabs.forEach((t) => t.addEventListener("click", () => setMode(t.dataset.mode)));
  $(".modes").addEventListener("keydown", (e) => {
    if (!["ArrowLeft", "ArrowRight"].includes(e.key)) return;
    e.preventDefault();
    const i = tabs.indexOf(document.activeElement);
    setMode(tabs[(i + 1) % tabs.length].dataset.mode, true);
  });
  document.querySelectorAll("[data-go-mode]").forEach((a) => a.addEventListener("click", () => setMode(a.dataset.goMode)));
  new ResizeObserver(place).observe($(".modes"));
  document.fonts?.ready.then(place);
}

async function init() {
  initValue();
  initReflect();
  initModes();
  initPreview();
  store.on("priority", () => state.data && renderExample());
  try {
    const res = await fetch(DATA_URL);
    if (!res.ok) throw new Error(`${res.status}`);
    state.data = await res.json();
    linkedState();
    store.setSource(`example-${state.practice}`);
    store.setDay(state.day);
    initExamples();
    // A link that names an example lands on the recap itself, not on the page's opening.
    if (new URLSearchParams(location.search).has("example")) {
      setTimeout(() => document.getElementById("recap").scrollIntoView({ block: "start", behavior: "instant" }), 0);
    }
  } catch {
    $("[data-ex-headline]").textContent = "The example practices couldn't be loaded.";
    $("[data-ex-sentences]").replaceChildren(el("p", {}, "Check your connection and refresh the page. Preview your own still works."));
  }
}

init();
